import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import benchmark from '../utils/benchmark_results.json';

// Generated by `npm run sync:benchmark` from database/seed/benchmark_results.json.
const { config, metricNotes, algorithms, alphaSensitivity } = benchmark;

const BASELINE_COLOUR = '#8a9ba1';
const HYBRID_COLOUR = '#165d5a';

function mean(entry, metric) {
  return entry.metrics[metric].mean;
}

function format(entry, metric, digits) {
  const { mean: m, sd } = entry.metrics[metric];
  if (m === null) {
    return '-';
  }
  return sd === null ? m.toFixed(digits) : `${m.toFixed(digits)} (${sd.toFixed(digits)})`;
}

// One row per algorithm, flat, so each chart reads straight from it. The fill
// colour is in the row: the hybrid stands out from the three baselines.
const rows = algorithms.map((algo) => ({
  key: algo.key,
  // Short name for chart axes: "Hybrid (alpha 0.4)" is too long and makes the
  // axis drop labels. The table keeps the full name.
  name: algo.key === 'hybrid' ? 'Hybrid' : algo.name,
  fill: algo.key === 'hybrid' ? HYBRID_COLOUR : BASELINE_COLOUR,
  gini: mean(algo, 'gini_coefficient'),
  avgResponse: mean(algo, 'avg_response_time_estimate'),
  highSeverity: mean(algo, 'high_severity_rate'),
  lowIncome: mean(algo, 'low_income_coverage'),
  compTime: mean(algo, 'computational_time_ms'),
}));

// The grouped chart colours bars by series (severity or low-income), so its rows
// must not carry the per-algorithm fill.
const queueRows = rows.map((row) => ({
  name: row.name,
  highSeverity: row.highSeverity,
  lowIncome: row.lowIncome,
}));

const alphaRows = alphaSensitivity.map((row) => ({
  alpha: row.alpha,
  gini: mean(row, 'gini_coefficient'),
  avgResponse: mean(row, 'avg_response_time_estimate'),
  highSeverity: mean(row, 'high_severity_rate'),
  lowIncome: mean(row, 'low_income_coverage'),
}));

const COLUMNS = [
  { metric: 'gini_coefficient', label: 'Gini (between wards)', digits: 3 },
  { metric: 'avg_response_time_estimate', label: 'Avg response (min)', digits: 1 },
  { metric: 'high_severity_rate', label: `Severity 4/5 in top ${config.highSeverityTopShare * 100}%`, digits: 3 },
  { metric: 'low_income_coverage', label: `Low-income in top ${config.lowIncomeTopShare * 100}%`, digits: 3 },
  { metric: 'computational_time_ms', label: 'Compute time (ms)', digits: 1 },
];

function AlgorithmComparisonPage() {
  return (
    <section className="benchmark-page">
      <p className="panel-message">
        Synthetic benchmark: {config.datasets} independent datasets, each with {config.requestsPerDataset} requests,{' '}
        {config.workersPerDataset} workers and {config.wards} wards. Every algorithm sees the same data. Table values
        are the mean across datasets, with the standard deviation in brackets. Hybrid uses alpha {config.hybridAlpha}.
      </p>

      <article className="chart-card">
        <h3>Metrics overview</h3>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Algorithm</th>
                {COLUMNS.map((col) => (
                  <th key={col.metric} title={metricNotes[col.metric]}>
                    {col.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {algorithms.map((algo) => (
                <tr key={algo.key} style={algo.key === 'hybrid' ? { fontWeight: 600 } : undefined}>
                  <td>{algo.name}</td>
                  {COLUMNS.map((col) => (
                    <td key={col.metric}>{format(algo, col.metric, col.digits)}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p style={{ marginBottom: 0, color: 'var(--muted)', fontSize: '0.9rem' }}>
          Read the Gini with care: it measures how similar the wards&apos; average waits are, not whether the outcome is
          fair. An algorithm that serves deprived wards faster on purpose scores a higher Gini. The two queue columns
          show the trade-off directly. A queue in random order scores about 0.2 on severity and about 0.5 on
          low-income coverage. A report counts as low-income when its ward SAMPI score is at least{' '}
          {config.lowIncomeSampiThreshold}, which covers {Math.round(config.shareInLowIncomeWards * 100)}% of the
          requests.
        </p>
      </article>

      <section className="chart-grid" style={{ marginTop: 14 }}>
        <article className="chart-card chart-card-wide">
          <h3>Who is served first: severity against low-income coverage</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={queueRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" interval={0} />
              <YAxis domain={[0, 1]} />
              <Tooltip formatter={(value) => Number(value).toFixed(3)} />
              <Legend />
              <ReferenceLine y={0.2} stroke="#9b2226" strokeDasharray="5 4" />
              <ReferenceLine y={0.5} stroke="#1d3557" strokeDasharray="5 4" />
              <Bar dataKey="highSeverity" name={`Severity 4/5 in top ${config.highSeverityTopShare * 100}%`} fill="#9b2226" />
              <Bar dataKey="lowIncome" name={`Low-income in top ${config.lowIncomeTopShare * 100}%`} fill="#1d3557" />
            </BarChart>
          </ResponsiveContainer>
          <p style={{ marginBottom: 0, color: 'var(--muted)', fontSize: '0.9rem' }}>
            The dashed lines show what a queue in random order would score: 0.2 for severity (red) and 0.5 for
            low-income coverage (blue). A bar above its line means that group is served earlier than chance.
          </p>
        </article>

        <article className="chart-card">
          <h3>Average response time (minutes)</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={rows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" interval={0} />
              <YAxis />
              <Tooltip formatter={(value) => `${Number(value).toFixed(1)} min`} />
              <Bar dataKey="avgResponse" name="Avg response (min)" />
            </BarChart>
          </ResponsiveContainer>
        </article>

        <article className="chart-card">
          <h3>Gini coefficient (between wards)</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={rows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" interval={0} />
              <YAxis domain={[0, 1]} />
              <Tooltip formatter={(value) => Number(value).toFixed(3)} />
              <Bar dataKey="gini" name="Gini" />
            </BarChart>
          </ResponsiveContainer>
        </article>

        <article className="chart-card chart-card-wide">
          <h3>Compute time per run of {config.requestsPerDataset} requests (ms, log scale)</h3>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={rows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" interval={0} />
              <YAxis scale="log" domain={[1, 'dataMax']} ticks={[1, 10, 100, 1000]} />
              <Tooltip formatter={(value) => `${Number(value).toFixed(1)} ms`} />
              <Bar dataKey="compTime" name="Compute time (ms)" />
            </BarChart>
          </ResponsiveContainer>
          <p style={{ marginBottom: 0, color: 'var(--muted)', fontSize: '0.9rem' }}>
            Genetic runs {config.geneticGenerations} generations here. Timings depend on the machine that ran the
            benchmark.
          </p>
        </article>

        <article className="chart-card">
          <h3>Hybrid across alpha: queue order</h3>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={alphaRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="alpha" label={{ value: 'alpha', position: 'insideBottom', offset: -2 }} />
              <YAxis domain={[0, 1]} />
              <Tooltip formatter={(value) => Number(value).toFixed(3)} />
              <Legend />
              <Line type="monotone" dataKey="lowIncome" name="Low-income in top 50%" stroke="#1d3557" strokeWidth={2} />
              <Line type="monotone" dataKey="highSeverity" name="Severity 4/5 in top 20%" stroke="#9b2226" strokeWidth={2} />
            </LineChart>
          </ResponsiveContainer>
        </article>

        <article className="chart-card">
          <h3>Hybrid across alpha: response time and Gini</h3>
          <ResponsiveContainer width="100%" height={280}>
            <LineChart data={alphaRows}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="alpha" label={{ value: 'alpha', position: 'insideBottom', offset: -2 }} />
              <YAxis yAxisId="minutes" />
              <YAxis yAxisId="gini" orientation="right" domain={[0, 1]} />
              <Tooltip />
              <Legend />
              <Line yAxisId="minutes" type="monotone" dataKey="avgResponse" name="Avg response (min)" stroke="#2d6a4f" strokeWidth={2} />
              <Line yAxisId="gini" type="monotone" dataKey="gini" name="Gini" stroke="#8884d8" strokeWidth={2} />
            </LineChart>
          </ResponsiveContainer>
        </article>
      </section>
    </section>
  );
}

export default AlgorithmComparisonPage;
